"""Parsing, stock keeping and pricing for stockroom.

Everything here is pure: functions take text or parsed objects and return
values, without touching the file system.
"""

from __future__ import annotations

import datetime as _dt
import re
from dataclasses import dataclass, field
from decimal import Decimal
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

__all__ = [
    "ParseError",
    "Product",
    "Movement",
    "Order",
    "QuoteLine",
    "Quote",
    "TAX_RATES",
    "parse_catalog",
    "parse_movements",
    "parse_orders",
    "parse_date",
    "first_negative",
    "counting_order",
    "stock_levels",
    "stock_status",
    "buy_quantity",
    "history",
    "available_on",
    "shipped_quantities",
    "order_status",
    "price_order",
    "price_lines",
    "format_amount",
    "format_movement",
]

# Tax rates in percent.
TAX_RATES = {"standard": 20, "reduced": 5, "zero": 0}

_SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_PRICE_RE = re.compile(r"([0-9]+)(?:\.([0-9]{1,2}))?")
_UINT_RE = re.compile(r"[0-9]+")
_SINT_RE = re.compile(r"[+-]?[0-9]+")
_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_ORDER_RE = re.compile(r"[Ss][Oo]-[0-9]+")
_LINE_ITEM_RE = re.compile(r"([A-Za-z]{2,4}-[0-9]{3})\*([0-9]+)")

# Fields are separated by spaces and tabs only.
_WS = " \t"
_MOVEMENT_RE = re.compile(
    r"[ \t]*([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*?))?[ \t]*", re.S
)
_TOKENS_RE = re.compile(r"[^ \t]+")


class ParseError(ValueError):
    """A line in a data file that does not follow the rules.

    ``line`` is the 1-based line number (blank and comment lines counted).
    ``filename`` is filled in by callers that know which file was read.
    """

    def __init__(self, line: int, reason: str, filename: Optional[str] = None):
        self.line = line
        self.reason = reason
        self.filename = filename
        super().__init__(f"line {line}: {reason}")

    def __str__(self) -> str:
        text = f"line {self.line}: {self.reason}"
        if self.filename:
            text = f"{self.filename}: {text}"
        return text


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"


@dataclass(frozen=True)
class Movement:
    date: _dt.date
    sku: str
    quantity: int
    note: str = ""
    line: int = field(default=0, compare=False)


@dataclass(frozen=True)
class Order:
    id: str
    date: _dt.date
    customer: str
    lines: List[Tuple[str, int]]
    line: int = field(default=0, compare=False)


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal
    order_discount: Decimal  # this line's share of the order discount (<= 0)
    taxable: Decimal
    tax: Decimal


@dataclass(frozen=True)
class Quote:
    id: str
    date: Optional[_dt.date]
    customer: str
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


# --------------------------------------------------------------------------
# Low-level helpers


def _lines(text: str) -> Iterable[Tuple[int, str]]:
    """Yield (number, line) for meaningful lines.

    Lines end at LF or CRLF only; a leading BOM is dropped; blank lines and
    comment lines are skipped (but still counted).
    """
    if text.startswith("﻿"):
        text = text[1:]
    for number, line in enumerate(text.split("\n"), start=1):
        if line.endswith("\r"):
            line = line[:-1]
        stripped = line.strip(_WS)
        if not stripped or stripped.startswith("#"):
            continue
        yield number, line


def _to_int(text: str) -> Optional[int]:
    try:
        return int(text)
    except ValueError:  # e.g. absurdly long numbers
        return None


def parse_date(text: str) -> Optional[_dt.date]:
    """Return the date for a ``YYYY-MM-DD`` string, or None if it is not one."""
    m = _DATE_RE.fullmatch(text)
    if not m:
        return None
    try:
        return _dt.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        return None


def _pennies_to_decimal(pennies: int) -> Decimal:
    sign = "-" if pennies < 0 else ""
    pennies = abs(pennies)
    return Decimal(f"{sign}{pennies // 100}.{pennies % 100:02d}")


def _decimal_to_pennies(value: Decimal) -> int:
    pennies = value * 100
    if pennies != pennies.to_integral_value():
        raise ValueError(f"{value} is not a whole number of pennies")
    return int(pennies)


def _round_half_up(numerator: int, denominator: int) -> int:
    """Round numerator/denominator (both >= 0) to the nearest int, halves up."""
    return (2 * numerator + denominator) // (2 * denominator)


def format_amount(value: Decimal) -> str:
    """Two decimals; never a negative zero."""
    if value == 0:
        return "0.00"
    return f"{value:.2f}"


def format_movement(movement: Movement) -> str:
    """A movement as written in movements.txt: ``DATE SKU ±QUANTITY [NOTE]``."""
    text = f"{movement.date.isoformat()} {movement.sku} {movement.quantity:+d}"
    if movement.note:
        text += " " + movement.note
    return text


# --------------------------------------------------------------------------
# Parsers


def parse_catalog(text: str) -> Dict[str, Product]:
    """Parse catalog.txt into a dict of SKU -> Product (in file order)."""
    catalog: Dict[str, Product] = {}
    for number, line in _lines(text):
        fields = [f.strip(_WS) for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(
                number,
                f"expected 4 or 5 fields separated by '|', found {len(fields)}",
            )
        sku, name, price, reorder = fields[:4]
        if not _SKU_RE.fullmatch(sku):
            raise ParseError(number, f"bad SKU {sku!r} (expected e.g. AB-100)")
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(number, f"duplicate SKU {sku}")
        if not name:
            raise ParseError(number, "empty product name")
        m = _PRICE_RE.fullmatch(price)
        if not m:
            raise ParseError(number, f"bad price {price!r}")
        whole = _to_int(m.group(1))
        if whole is None:
            raise ParseError(number, f"bad price {price!r}")
        pennies = whole * 100 + int((m.group(2) or "").ljust(2, "0"))
        if pennies < 1:
            raise ParseError(number, f"bad price {price!r} (must be at least 0.01)")
        if not _UINT_RE.fullmatch(reorder) or _to_int(reorder) is None:
            raise ParseError(number, f"bad reorder level {reorder!r}")
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower()
            if tax not in TAX_RATES:
                raise ParseError(
                    number,
                    f"bad tax band {fields[4]!r} (expected standard, reduced or zero)",
                )
        catalog[sku] = Product(
            sku=sku,
            name=name,
            price=_pennies_to_decimal(pennies),
            reorder=int(reorder),
            tax=tax,
        )
    return catalog


def counting_order(movements: Sequence[Movement]) -> List[Movement]:
    """Movements in the order they count: by date, file order within a day."""
    return sorted(movements, key=lambda m: m.date)


def first_negative(movements: Sequence[Movement]) -> Optional[Tuple[Movement, int]]:
    """The first movement (in counting order) that takes a stock below zero.

    Returns (movement, balance after it), or None when every stock stays at
    zero or above.
    """
    balances: Dict[str, int] = {}
    for m in counting_order(movements):
        balance = balances.get(m.sku, 0) + m.quantity
        balances[m.sku] = balance
        if balance < 0:
            return m, balance
    return None


def parse_movements(text: str, catalog: Dict[str, Product]) -> List[Movement]:
    """Parse movements.txt into a list of Movements in file order."""
    movements: List[Movement] = []
    for number, line in _lines(text):
        m = _MOVEMENT_RE.fullmatch(line)
        if not m:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date_text, sku, qty_text, note = m.groups()
        date = parse_date(date_text)
        if date is None:
            raise ParseError(number, f"bad date {date_text!r} (expected YYYY-MM-DD)")
        if not _SKU_RE.fullmatch(sku) or sku.upper() not in catalog:
            raise ParseError(number, f"unknown SKU {sku!r}")
        if not _SINT_RE.fullmatch(qty_text):
            raise ParseError(number, f"bad quantity {qty_text!r}")
        quantity = _to_int(qty_text)
        if quantity is None:
            raise ParseError(number, f"bad quantity {qty_text!r}")
        if quantity == 0:
            raise ParseError(number, "quantity may not be zero")
        movements.append(
            Movement(date=date, sku=sku.upper(), quantity=quantity,
                     note=note or "", line=number)
        )
    bad = first_negative(movements)
    if bad is not None:
        mv, balance = bad
        raise ParseError(
            mv.line,
            f"stock of {mv.sku} goes below zero ({balance}) on {mv.date.isoformat()}",
        )
    return movements


def parse_orders(text: str, catalog: Dict[str, Product]) -> List[Order]:
    """Parse orders.txt into a list of Orders in file order."""
    orders: List[Order] = []
    seen = set()
    for number, line in _lines(text):
        tokens = _TOKENS_RE.findall(line)
        if len(tokens) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES")
        order_id, date_text, customer, items = tokens
        if not _ORDER_RE.fullmatch(order_id):
            raise ParseError(number, f"bad order number {order_id!r} (expected e.g. SO-1001)")
        order_id = order_id.upper()
        if order_id in seen:
            raise ParseError(number, f"duplicate order {order_id}")
        date = parse_date(date_text)
        if date is None:
            raise ParseError(number, f"bad date {date_text!r} (expected YYYY-MM-DD)")
        lines: List[Tuple[str, int]] = []
        skus = set()
        for item in items.split(","):
            im = _LINE_ITEM_RE.fullmatch(item)
            if not im:
                raise ParseError(number, f"bad order line {item!r} (expected SKU*QUANTITY)")
            sku = im.group(1).upper()
            if sku not in catalog:
                raise ParseError(number, f"unknown SKU {im.group(1)!r}")
            if sku in skus:
                raise ParseError(number, f"SKU {sku} appears more than once")
            quantity = _to_int(im.group(2))
            if quantity is None or quantity < 1:
                raise ParseError(number, f"bad quantity {im.group(2)!r} (must be 1 or more)")
            skus.add(sku)
            lines.append((sku, quantity))
        seen.add(order_id)
        orders.append(
            Order(id=order_id, date=date, customer=customer, lines=lines, line=number)
        )
    return orders


# --------------------------------------------------------------------------
# Shelves


def stock_levels(catalog: Dict[str, Product], movements: Iterable[Movement]) -> Dict[str, int]:
    """SKU -> quantity on the shelf, for every product in the catalogue."""
    levels = {sku: 0 for sku in catalog}
    for m in movements:
        levels[m.sku] = levels.get(m.sku, 0) + m.quantity
    return levels


def stock_status(onhand: int, reorder: int) -> str:
    if onhand <= 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def buy_quantity(onhand: int, reorder: int) -> int:
    return max(1, 2 * reorder - onhand)


def history(sku: str, movements: Sequence[Movement]) -> List[Tuple[Movement, int]]:
    """(movement, balance after it) for one SKU, in counting order."""
    sku = sku.upper()
    balance = 0
    rows = []
    for m in counting_order(movements):
        if m.sku == sku:
            balance += m.quantity
            rows.append((m, balance))
    return rows


def available_on(sku: str, date: _dt.date, movements: Sequence[Movement]) -> int:
    """How many of ``sku`` can leave the shelf on ``date``.

    No more than the stock after every movement dated on or before ``date``,
    and no more than the lowest stock at any later point.
    """
    sku = sku.upper()
    balance = 0
    at_date: Optional[int] = None
    lowest_later: Optional[int] = None
    for m in counting_order(movements):
        if m.date > date and at_date is None:
            at_date = balance
        if m.sku == sku:
            balance += m.quantity
            if m.date > date:
                lowest_later = balance if lowest_later is None else min(lowest_later, balance)
    if at_date is None:
        at_date = balance
    result = at_date if lowest_later is None else min(at_date, lowest_later)
    return max(0, result)


def shipped_quantities(order: Order, movements: Iterable[Movement]) -> Dict[str, int]:
    """SKU -> units shipped so far for each line of ``order``.

    Counts the negative movements whose note is exactly ``order <ID>``,
    capped at the quantity ordered.
    """
    note = f"order {order.id.upper()}"
    sent: Dict[str, int] = {sku: 0 for sku, _ in order.lines}
    for m in movements:
        if m.note == note and m.quantity < 0 and m.sku in sent:
            sent[m.sku] += -m.quantity
    return {sku: min(qty, sent[sku]) for sku, qty in order.lines}


def order_status(order: Order, shipped: Dict[str, int]) -> str:
    if all(shipped.get(sku, 0) >= qty for sku, qty in order.lines):
        return "complete"
    if all(shipped.get(sku, 0) == 0 for sku, _ in order.lines):
        return "open"
    return "partial"


# --------------------------------------------------------------------------
# Prices


def price_lines(
    lines: Sequence[Tuple[str, int]],
    catalog: Dict[str, Product],
    order_id: str = "",
    date: Optional[_dt.date] = None,
    customer: str = "",
) -> Quote:
    """Price a list of (sku, quantity) pairs. See ``price_order``."""
    # All arithmetic in whole pennies, so it is exact.
    products = []
    for sku, quantity in lines:
        product = catalog.get(sku.upper())
        if product is None:
            raise ValueError(f"unknown SKU {sku!r}")
        if quantity < 1:
            raise ValueError(f"bad quantity {quantity!r} for {sku}")
        products.append((product, int(quantity)))

    rows = []
    for product, quantity in products:
        unit = _decimal_to_pennies(product.price)
        gross = unit * quantity
        rate = 10 if quantity >= 50 else 5 if quantity >= 10 else 0
        discount = _round_half_up(gross * rate, 100)
        rows.append([product, quantity, unit, gross, discount, gross - discount])

    subtotal = sum(r[5] for r in rows)
    order_discount = _round_half_up(subtotal * 3, 100) if subtotal >= 50000 else 0

    # Share the order discount out in proportion to the nets.
    shares = [0] * len(rows)
    if order_discount:
        remainders = []
        for i, r in enumerate(rows):
            shares[i], rem = divmod(order_discount * r[5], subtotal)
            remainders.append((-rem, i))
        left = order_discount - sum(shares)
        for _, i in sorted(remainders)[:left]:
            shares[i] += 1

    quote_lines = []
    tax_total = 0
    for (product, quantity, unit, gross, discount, net), share in zip(rows, shares):
        taxable = net - share
        tax = _round_half_up(taxable * TAX_RATES[product.tax], 100)
        tax_total += tax
        quote_lines.append(
            QuoteLine(
                sku=product.sku,
                quantity=quantity,
                unit=_pennies_to_decimal(unit),
                gross=_pennies_to_decimal(gross),
                discount=_pennies_to_decimal(-discount),
                net=_pennies_to_decimal(net),
                order_discount=_pennies_to_decimal(-share),
                taxable=_pennies_to_decimal(taxable),
                tax=_pennies_to_decimal(tax),
            )
        )
    return Quote(
        id=order_id,
        date=date,
        customer=customer,
        lines=quote_lines,
        subtotal=_pennies_to_decimal(subtotal),
        order_discount=_pennies_to_decimal(-order_discount),
        tax=_pennies_to_decimal(tax_total),
        total=_pennies_to_decimal(subtotal - order_discount + tax_total),
    )


def price_order(order: Order, catalog: Dict[str, Product]) -> Quote:
    """Price a whole order: volume discounts, order discount, tax, total."""
    return price_lines(order.lines, catalog, order.id, order.date, order.customer)

