class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal
    order_discount: Decimal  # this line's share of the order discount (<= 0)
    taxable: Decimal
    tax: Decimal


