    """Return the date for a ``YYYY-MM-DD`` string, or None if it is not one."""
    m = _DATE_RE.fullmatch(text)
    if not m:
        return None
    try:
        return _dt.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        return None


