    sign = "-" if pennies < 0 else ""
    pennies = abs(pennies)
    return Decimal(f"{sign}{pennies // 100}.{pennies % 100:02d}")


def _decimal_to_pennies(value: Decimal) -> int:
    pennies = value * 100
    if pennies != pennies.to_integral_value():
        raise ValueError(f"{value} is not a whole number of pennies")
    return int(pennies)


