        if len(fields) == 5:
            tax = fields[4].lower()
            if tax not in TAX_RATES:
                raise ParseError(
                    number,
                    f"bad tax band {fields[4]!r} (expected standard, reduced or zero)",
                )
        catalog[sku] = Product(
            sku=sku,
            name=name,
            price=_pennies_to_decimal(pennies),
            reorder=int(reorder),
            tax=tax,
        )
