def order_status(order: Order, shipped: Dict[str, int]) -> str:
    if all(shipped.get(sku, 0) >= qty for sku, qty in order.lines):
        return "complete"
    if all(shipped.get(sku, 0) == 0 for sku, _ in order.lines):
