# --------------------------------------------------------------------------
# Prices


def price_lines(
    lines: Sequence[Tuple[str, int]],
    catalog: Dict[str, Product],
    order_id: str = "",
    date: Optional[_dt.date] = None,
    customer: str = "",
) -> Quote:
    """Price a list of (sku, quantity) pairs. See ``price_order``."""
    # All arithmetic in whole pennies, so it is exact.
    products = []
    for sku, quantity in lines:
        product = catalog.get(sku.upper())
        if product is None:
            raise ValueError(f"unknown SKU {sku!r}")
        if quantity < 1:
            raise ValueError(f"bad quantity {quantity!r} for {sku}")
        products.append((product, int(quantity)))

    rows = []
    for product, quantity in products:
        unit = _decimal_to_pennies(product.price)
        gross = unit * quantity
        rate = 10 if quantity >= 50 else 5 if quantity >= 10 else 0
        discount = _round_half_up(gross * rate, 100)
        rows.append([product, quantity, unit, gross, discount, gross - discount])

    subtotal = sum(r[5] for r in rows)
    order_discount = _round_half_up(subtotal * 3, 100) if subtotal >= 50000 else 0

    # Share the order discount out in proportion to the nets.
    shares = [0] * len(rows)
    if order_discount:
        remainders = []
        for i, r in enumerate(rows):
            shares[i], rem = divmod(order_discount * r[5], subtotal)
            remainders.append((-rem, i))
        left = order_discount - sum(shares)
        for _, i in sorted(remainders)[:left]:
            shares[i] += 1

    quote_lines = []
    tax_total = 0
    for (product, quantity, unit, gross, discount, net), share in zip(rows, shares):
        taxable = net - share
        tax = _round_half_up(taxable * TAX_RATES[product.tax], 100)
        tax_total += tax
        quote_lines.append(
            QuoteLine(
                sku=product.sku,
                quantity=quantity,
                unit=_pennies_to_decimal(unit),
                gross=_pennies_to_decimal(gross),
                discount=_pennies_to_decimal(-discount),
                net=_pennies_to_decimal(net),
                order_discount=_pennies_to_decimal(-share),
                taxable=_pennies_to_decimal(taxable),
                tax=_pennies_to_decimal(tax),
            )
        )
    return Quote(
        id=order_id,
        date=date,
        customer=customer,
        lines=quote_lines,
        subtotal=_pennies_to_decimal(subtotal),
        order_discount=_pennies_to_decimal(-order_discount),
        tax=_pennies_to_decimal(tax_total),
        total=_pennies_to_decimal(subtotal - order_discount + tax_total),
    )


def price_order(order: Order, catalog: Dict[str, Product]) -> Quote:
    """Price a whole order: volume discounts, order discount, tax, total."""
    return price_lines(order.lines, catalog, order.id, order.date, order.customer)

