"""The ``stockroom`` command."""

from __future__ import annotations

import csv
import io
import json
import os
import sys
from typing import Dict, List, Optional, Sequence, Tuple

from . import core
from .core import (
    Movement,
    ParseError,
    format_amount,
    format_movement,
    parse_date,
)

USAGE = """\
usage: stockroom [--dir DIR] COMMAND [ARGS]

the shelves:
  stock [--json]                          what is on the shelves
  low [--json]                            what needs buying
  history SKU [--json]                    one product's movements
  receive DATE SKU QUANTITY [NOTE]        record stock coming in
  ship DATE SKU QUANTITY [NOTE]           record stock going out

the orders:
  quote ORDER [--json]                    price an order
  fulfil ORDER DATE                       ship what the shelves can cover
  invoice ORDER [--json]                  price what has shipped
  report [--format text|csv|json]         one row per order

--dir DIR   folder holding catalog.txt, movements.txt and orders.txt
            (default: the current folder)
"""

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"


class UsageError(Exception):
    """Something wrong with the command line (exit 2)."""


class FileError(Exception):
    """A file that cannot be read or written (exit 2)."""


class Refused(Exception):
    """A request that cannot be carried out (exit 1)."""


# --------------------------------------------------------------------------
# Command line

# command -> (allowed options, min positionals, max positionals, raw)
# "raw" commands take every argument as typed (only --dir is an option).
COMMANDS = {
    "stock": ({"--json"}, 0, 0, False),
    "low": ({"--json"}, 0, 0, False),
    "history": ({"--json"}, 1, 1, False),
    "receive": (set(), 3, 4, True),
    "ship": (set(), 3, 4, True),
    "quote": ({"--json"}, 1, 1, False),
    "fulfil": (set(), 2, 2, True),
    "invoice": ({"--json"}, 1, 1, False),
    "report": ({"--format"}, 0, 0, False),
}
FORMATS = ("text", "csv", "json")


class Request:
    def __init__(self) -> None:
        self.directory = "."
        self.command = ""
        self.args: List[str] = []
        self.json = False
        self.format = "text"
        self.help = False


def parse_command_line(argv: Sequence[str]) -> Request:
    req = Request()
    rest: List[str] = []
    # --dir may appear anywhere on the line.
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise UsageError("--dir needs a folder")
            req.directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            req.directory = arg[len("--dir="):]
            i += 1
            continue
        rest.append(arg)
        i += 1

    if rest and rest[0] in ("-h", "--help"):
        req.help = True
        return req

    # Find the command: the first word that is not an option (or the value
    # of --format).
    index = None
    i = 0
    while i < len(rest):
        arg = rest[i]
        if arg == "--format":
            i += 2
            continue
        if arg.startswith("-") and arg != "-":
            i += 1
            continue
        index = i
        break
    if index is None:
        if rest:
            raise UsageError(f"unknown option {rest[0]!r}" if rest[0] not in
                             ("--json", "--format") and not rest[0].startswith("--format=")
                             else "no command given")
        raise UsageError("no command given")
    command = rest[index]
    if command not in COMMANDS:
        raise UsageError(f"unknown command {command!r}")
    req.command = command
    options, low, high, raw = COMMANDS[command]
    before, after = rest[:index], rest[index + 1:]

    positionals: List[str] = []
    if raw:
        if before:
            raise UsageError(f"unknown option {before[0]!r}")
        positionals = list(after)
    else:
        words = before + after
        i = 0
        only_positionals = False
        while i < len(words):
            arg = words[i]
            i += 1
            if only_positionals or arg == "-" or not arg.startswith("-"):
                positionals.append(arg)
                continue
            if arg == "--":
                only_positionals = True
                continue
            if arg in ("-h", "--help"):
                req.help = True
                continue
            name, eq, value = arg.partition("=")
            if name not in options:
                raise UsageError(f"unknown option {arg!r} for {command}")
            if name == "--json":
                if eq:
                    raise UsageError("--json takes no value")
                req.json = True
            elif name == "--format":
                if not eq:
                    if i >= len(words):
                        raise UsageError("--format needs a value (text, csv or json)")
                    value = words[i]
                    i += 1
                if value not in FORMATS:
                    raise UsageError(f"bad --format {value!r} (expected text, csv or json)")
                req.format = value
        if req.help:
            return req

    if not low <= len(positionals) <= high:
        expected = str(low) if low == high else f"{low} or {high}"
        raise UsageError(
            f"{command} takes {expected} argument{'s' if high != 1 else ''}, "
            f"got {len(positionals)}"
        )
    req.args = positionals

    # Dates on the command line are checked here.
    if command in ("receive", "ship"):
        if parse_date(positionals[0]) is None:
            raise UsageError(f"bad date {positionals[0]!r} (expected YYYY-MM-DD)")
    elif command == "fulfil":
        if parse_date(positionals[1]) is None:
            raise UsageError(f"bad date {positionals[1]!r} (expected YYYY-MM-DD)")
    return req


# --------------------------------------------------------------------------
# Files


def _read_bytes(directory: str, name: str, required: bool) -> Optional[bytes]:
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as fh:
            return fh.read()
    except FileNotFoundError:
        if required:
            raise FileError(f"{name}: not found in {directory}")
        return None
    except IsADirectoryError:
        raise FileError(f"{name}: is a folder, not a file")
    except OSError as exc:
        raise FileError(f"{name}: cannot read: {exc.strerror or exc}")


def _decode(name: str, data: Optional[bytes]) -> str:
    if data is None:
        return ""
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError as exc:
        line = data.count(b"\n", 0, exc.start) + 1
        raise FileError(f"{name}: line {line}: not valid UTF-8")


class Files:
    """The data files a command needs, read and parsed."""

    def __init__(self, directory: str, movements: bool, orders: bool) -> None:
        if not os.path.exists(directory):
            raise FileError(f"folder {directory!r} does not exist")
        if not os.path.isdir(directory):
            raise FileError(f"{directory!r} is not a folder")
        self.directory = directory
        # Read everything first (exit 2 on trouble), then parse (exit 1).
        catalog_text = _decode(CATALOG, _read_bytes(directory, CATALOG, True))
        self.movements_raw = None
        movements_text = orders_text = ""
        if movements:
            self.movements_raw = _read_bytes(directory, MOVEMENTS, False)
            movements_text = _decode(MOVEMENTS, self.movements_raw)
        if orders:
            orders_text = _decode(ORDERS, _read_bytes(directory, ORDERS, False))

        self.catalog = _parse(CATALOG, core.parse_catalog, catalog_text)
        self.movements: List[Movement] = []
        self.orders: List[core.Order] = []
        if movements:
            self.movements = _parse(MOVEMENTS, core.parse_movements, movements_text,
                                    self.catalog)
        if orders:
            self.orders = _parse(ORDERS, core.parse_orders, orders_text, self.catalog)

    def order(self, order_id: str) -> core.Order:
        wanted = order_id.upper()
        for order in self.orders:
            if order.id == wanted:
                return order
        raise Refused(f"{ORDERS}: no order {order_id!r}")

    def product(self, sku: str) -> core.Product:
        product = self.catalog.get(sku.upper())
        if product is None:
            raise Refused(f"{CATALOG}: no product {sku!r}")
        return product

    def append_movements(self, movements: Sequence[Movement]) -> None:
        if not movements:
            return
        text = "".join(format_movement(m) + "\n" for m in movements)
        data = text.encode("utf-8")
        raw = self.movements_raw or b""
        if raw and not raw.endswith(b"\n"):
            data = b"\n" + data
        path = os.path.join(self.directory, MOVEMENTS)
        try:
            with open(path, "ab") as fh:
                fh.write(data)
        except OSError as exc:
            raise FileError(f"{MOVEMENTS}: cannot write: {exc.strerror or exc}")


def _parse(name, parser, *args):
    try:
        return parser(*args)
    except ParseError as exc:
        exc.filename = name
        raise


# --------------------------------------------------------------------------
# Commands


def _json(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def cmd_stock(req: Request, files: Files) -> str:
    levels = core.stock_levels(files.catalog, files.movements)
    rows = []
    for sku in sorted(files.catalog):
        product = files.catalog[sku]
        onhand = levels[sku]
        rows.append((product, onhand, core.stock_status(onhand, product.reorder)))
    if req.json:
        return _json([
            {"sku": p.sku, "name": p.name, "onhand": n, "status": s} for p, n, s in rows
        ])
    return "".join(f"{p.sku} {n} {s} {p.name}\n" for p, n, s in rows)


def cmd_low(req: Request, files: Files) -> str:
    levels = core.stock_levels(files.catalog, files.movements)
    rows = []
    for sku in sorted(files.catalog):
        product = files.catalog[sku]
        onhand = levels[sku]
        if core.stock_status(onhand, product.reorder) in ("low", "out"):
            rows.append((sku, onhand, product.reorder,
                         core.buy_quantity(onhand, product.reorder)))
    if req.json:
        return _json([
            {"sku": s, "onhand": n, "reorder": r, "buy": b} for s, n, r, b in rows
        ])
    return "".join(f"{s} {n} {r} {b}\n" for s, n, r, b in rows)


def cmd_history(req: Request, files: Files) -> str:
    product = files.product(req.args[0])
    rows = core.history(product.sku, files.movements)
    if req.json:
        return _json([
            {"date": m.date.isoformat(), "delta": f"{m.quantity:+d}",
             "balance": balance, "note": m.note}
            for m, balance in rows
        ])
    out = []
    for m, balance in rows:
        line = f"{m.date.isoformat()} {m.quantity:+d} {balance}"
        if m.note:
            line += " " + m.note
        out.append(line + "\n")
    return "".join(out)


def _add_movement(req: Request, files: Files, sign: int) -> str:
    date_text, sku_text, qty_text = req.args[:3]
    note = req.args[3] if len(req.args) > 3 else ""
    product = files.product(sku_text)
    if not core._UINT_RE.fullmatch(qty_text):
        raise Refused(f"bad quantity {qty_text!r} (expected a whole number of 1 or more)")
    quantity = core._to_int(qty_text)
    if quantity is None or quantity < 1:
        raise Refused(f"bad quantity {qty_text!r} (expected a whole number of 1 or more)")
    if "\n" in note or "\r" in note:
        raise Refused("a note may not contain a line break")
    note = note.strip(" \t")
    movement = Movement(date=parse_date(date_text), sku=product.sku,
                        quantity=sign * quantity, note=note)
    bad = core.first_negative(list(files.movements) + [movement])
    if bad is not None:
        mv, balance = bad
        raise Refused(
            f"{MOVEMENTS}: refused: stock of {mv.sku} would go below zero "
            f"({balance}) on {mv.date.isoformat()}"
            + (f" at line {mv.line}" if mv is not movement and mv.line else "")
        )
    files.append_movements([movement])
    return format_movement(movement) + "\n"


def cmd_receive(req: Request, files: Files) -> str:
    return _add_movement(req, files, +1)


def cmd_ship(req: Request, files: Files) -> str:
    return _add_movement(req, files, -1)


def _quote_output(quote: core.Quote, as_json: bool, header_prefix: str = "") -> str:
    if as_json:
        return _json({
            "order": quote.id,
            "date": quote.date.isoformat() if quote.date else None,
            "customer": quote.customer,
            "lines": [
                {
                    "sku": line.sku,
                    "quantity": line.quantity,
                    "unit": format_amount(line.unit),
                    "gross": format_amount(line.gross),
                    "discount": format_amount(line.discount),
                    "net": format_amount(line.net),
                }
                for line in quote.lines
            ],
            "subtotal": format_amount(quote.subtotal),
            "order_discount": format_amount(quote.order_discount),
            "tax": format_amount(quote.tax),
            "total": format_amount(quote.total),
        })
    out = [f"{header_prefix}{quote.id} {quote.date.isoformat()} {quote.customer}\n"]
    for line in quote.lines:
        out.append(
            f"{line.sku} {line.quantity} {format_amount(line.unit)} "
            f"{format_amount(line.gross)} {format_amount(line.discount)} "
            f"{format_amount(line.net)}\n"
        )
    out.append(f"subtotal {format_amount(quote.subtotal)}\n")
    out.append(f"order discount {format_amount(quote.order_discount)}\n")
    out.append(f"tax {format_amount(quote.tax)}\n")
    out.append(f"total {format_amount(quote.total)}\n")
    return "".join(out)


def cmd_quote(req: Request, files: Files) -> str:
    order = files.order(req.args[0])
    return _quote_output(core.price_order(order, files.catalog), req.json)


def _invoice_quote(order: core.Order, files: Files) -> Optional[core.Quote]:
    shipped = core.shipped_quantities(order, files.movements)
    lines = [(sku, shipped[sku]) for sku, _ in order.lines if shipped[sku] > 0]
    if not lines:
        return None
    return core.price_lines(lines, files.catalog, order.id, order.date, order.customer)


def cmd_invoice(req: Request, files: Files) -> str:
    order = files.order(req.args[0])
    quote = _invoice_quote(order, files)
    if quote is None:
        raise Refused(f"nothing has shipped yet on order {order.id}")
    return _quote_output(quote, req.json, "invoice ")


def cmd_fulfil(req: Request, files: Files) -> str:
    order = files.order(req.args[0])
    date = parse_date(req.args[1])
    if date < order.date:
        raise Refused(
            f"cannot fulfil {order.id} on {date.isoformat()}: "
            f"it was ordered on {order.date.isoformat()}"
        )
    shipped = core.shipped_quantities(order, files.movements)
    note = f"order {order.id}"
    new: List[Movement] = []
    results: List[Tuple[str, int, int]] = []
    for sku, quantity in order.lines:
        owed = quantity - shipped[sku]
        send = min(owed, core.available_on(sku, date, files.movements)) if owed else 0
        if send > 0:
            new.append(Movement(date=date, sku=sku, quantity=-send, note=note))
            shipped[sku] += send
        results.append((sku, send, owed - send))
    # Belt and braces: never write a file that breaks the rules.
    if core.first_negative(list(files.movements) + new) is not None:
        raise Refused(f"{MOVEMENTS}: refused: shipping {order.id} would take stock below zero")
    files.append_movements(new)
    out = [f"{sku} shipped {n} backordered {m}\n" for sku, n, m in results]
    out.append(f"status {core.order_status(order, shipped)}\n")
    return "".join(out)


def cmd_report(req: Request, files: Files) -> str:
    rows = []
    orders = sorted(files.orders, key=lambda o: (o.date, int(o.id[3:]), o.id))
    for order in orders:
        shipped = core.shipped_quantities(order, files.movements)
        invoice = _invoice_quote(order, files)
        rows.append({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "status": core.order_status(order, shipped),
            "ordered": sum(q for _, q in order.lines),
            "shipped": sum(shipped.values()),
            "quoted": format_amount(core.price_order(order, files.catalog).total),
            "invoiced": format_amount(invoice.total) if invoice else "0.00",
        })
    if req.format == "json":
        return _json(rows)
    if req.format == "csv":
        buf = io.StringIO()
        fields = ["order", "date", "customer", "status", "ordered", "shipped",
                  "quoted", "invoiced"]
        writer = csv.DictWriter(buf, fieldnames=fields, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)
        return buf.getvalue()
    return "".join(
        f"{r['order']} {r['date']} {r['customer']} {r['status']} "
        f"{r['shipped']}/{r['ordered']} {r['quoted']} {r['invoiced']}\n"
        for r in rows
    )


HANDLERS = {
    "stock": (cmd_stock, True, False),
    "low": (cmd_low, True, False),
    "history": (cmd_history, True, False),
    "receive": (cmd_receive, True, False),
    "ship": (cmd_ship, True, False),
    "quote": (cmd_quote, False, True),
    "fulfil": (cmd_fulfil, True, True),
    "invoice": (cmd_invoice, True, True),
    "report": (cmd_report, True, True),
}


# --------------------------------------------------------------------------
# Entry point


def _write(stream, text: str) -> None:
    data = text.encode("utf-8", "surrogateescape")
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        stream.flush()
        buffer.write(data)
        buffer.flush()
    else:
        stream.write(text)
        stream.flush()


def _error(message: str) -> None:
    try:
        _write(sys.stderr, f"stockroom: {message}\n")
    except (OSError, ValueError):
        pass


def run(argv: Sequence[str]) -> int:
    try:
        req = parse_command_line(argv)
    except UsageError as exc:
        _error(str(exc))
        _error("try 'stockroom --help'")
        return 2
    if req.help:
        _write(sys.stdout, USAGE)
        return 0
    handler, movements, orders = HANDLERS[req.command]
    try:
        files = Files(req.directory, movements, orders)
        output = handler(req, files)
    except FileError as exc:
        _error(str(exc))
        return 2
    except ParseError as exc:
        _error(str(exc))
        return 1
    except Refused as exc:
        _error(str(exc))
        return 1
    _write(sys.stdout, output)
    return 0


def main(argv: Optional[Sequence[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    try:
        return run(argv)
    except BrokenPipeError:
        # Whoever was reading went away: stop quietly. Point stdout at
        # /dev/null so the interpreter's final flush does not complain.
        try:
            devnull = os.open(os.devnull, os.O_WRONLY)
            os.dup2(devnull, sys.stdout.fileno())
        except (OSError, ValueError):
            pass
        return 0
    except KeyboardInterrupt:
        return 130


def entry_point() -> None:
    sys.exit(main())

